SET @prov_c := '%s';
SET @id := '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');
SET @prov5 := (SELECT hoscode FROM sys_config c INNER JOIN chospital h ON c.provincecode=h.provcode AND h.hostype in(1));


CREATE TABLE IF NOT EXISTS s_telemed_hosp(
id varchar(32) NOT NULL,
hospcode varchar(5) NOT NULL,
areacode varchar(8) NOT NULL,
flag_sent varchar(1) NOT NULL,
date_com varchar(14) NOT NULL,
b_year varchar(4) NOT NULL,
result INT(9) DEFAULT 0,
PRIMARY KEY (id,hospcode,areacode,b_year),
  KEY (hospcode),
  KEY (areacode),
  KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_telemed_hosp WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_telemed_hosp
SELECT @id,h.hoscode,concat(h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2)) as areacode
 ,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
,COUNT(DISTINCT IF(s.typein IN(5),CONCAT(s.hospcode,'-',s.pid,'-',s.seq),NULL)) as result

FROM chospital h 
INNER JOIN tmp_service s  ON h.hoscode=s.hospcode
INNER JOIN t_person_db p ON s.hospcode=p.hospcode AND s.pid=p.pid 
WHERE h.hostype in(5,6,7,8,9,18) AND dep='21002' AND h.mcode = '21000' AND s.DATE_SERV BETWEEN @start_d AND @end_d AND  h.PROVCODE=@prov_c
GROUP BY h.hoscode;

DELETE FROM s_telemed_hosp WHERE result=0;

